/** RefundBot's endpoints, for targets that don't declare their own. */
export const REFUNDBOT_ENDPOINTS = ['orders.get', 'refunds.create', 'email.send', 'policy.search'];

// One catalog per target, keyed by target name, so a patched copy of a target
// (loaded from a workspace) sees the same catalog, generated faults included.
const CATALOGS = new Map<string, Fault[]>([
  ['refundbot', FAULTS],
  ['researchbot', RESEARCH_FAULTS],
]);

/** A target (or just its name). Omitted means RefundBot, so older callers keep working. */
export type TargetRef = { name: string; endpoints?: Record<string, string> } | string | undefined;
const nameOf = (t: TargetRef) => (typeof t === 'string' ? t : t?.name) ?? 'refundbot';

/** The endpoints faults may name for a target: its declared endpoints (RefundBot's by default) plus 'ticket'. */
export function endpointsOf(target: TargetRef): string[] {
  const declared = typeof target === 'object' && target.endpoints ? Object.keys(target.endpoints) : REFUNDBOT_ENDPOINTS;
  return [...declared, 'ticket'];
}

/**
 * The fault catalog for a target (RefundBot's when none is named). Throws if a
 * fault names an endpoint the target doesn't serve, so a catalog can never be
 * run against the wrong agent by accident.
 */
export function faultsFor(target?: TargetRef): Fault[] {
  const name = nameOf(target);
  const catalog = CATALOGS.get(name);
  if (!catalog) throw new Error(`no fault catalog for target "${name}". Known: ${[...CATALOGS.keys()].join(', ')}`);
  if (typeof target === 'object' && target.endpoints) {
    const ok = new Set(endpointsOf(target));
    const bad = catalog.find((f) => !ok.has(f.endpoint));
    if (bad) throw new Error(`fault "${bad.id}" names endpoint "${bad.endpoint}", which ${name} does not serve (${[...ok].join(', ')})`);
  }
  return catalog;
}

/** Adds faults (e.g. generative Red's accepted specs) to a target's catalog, so every consumer sees them. */
export function registerFaults(faults: Fault[], target?: TargetRef): Fault[] {
  const catalog = faultsFor(target);
  for (const f of faults) {
    if (catalog.some((x) => x.id === f.id)) throw new Error(`fault "${f.id}" is already in the catalog`);
    catalog.push(f);
  }
  return catalog;
}

export function getFault(id: string, target?: TargetRef): Fault {
  const catalog = faultsFor(target);
  const fault = catalog.find((f) => f.id === id);
  if (!fault) throw new Error(`unknown fault "${id}" for ${nameOf(target)}. Known: ${catalog.map((f) => f.id).join(', ')}`);
  return fault;
}

/** Applies a ticket-level fault to the trial's ticket. Other faults leave it (and the rng) untouched. */
export function injectTicket<T extends TicketLike>(ticket: T, fault: Fault | undefined, ctx: FaultContext): T {
  if (!fault || fault.endpoint !== 'ticket' || !fault.rewriteTicket) return ticket;
  if (ctx.rng() >= fault.rate) return ticket;
  ctx.fired++;
  log('chaos: injecting {fault} into the ticket', { fault: fault.id, level: 'warn' });
  return fault.rewriteTicket(ticket, ctx);
}

export function injectFault<T extends Transport<any>>(transport: T, fault: Fault | undefined, ctx: FaultContext): T {
  if (!fault || fault.endpoint === 'ticket') return transport;
  const trialHit = fault.scope === 'trial' ? ctx.rng() < fault.rate : true;
  const injected: Transport = async (endpoint, payload) => {
    const next = (p: Record<string, unknown> = payload) => transport(endpoint, p);
    if (endpoint !== fault.endpoint || !trialHit) return next();
    if (fault.scope === 'call' && ctx.rng() >= fault.rate) return next();
    ctx.fired++;
    log('chaos: injecting {fault} on {endpoint}', { fault: fault.id, endpoint, level: 'warn' });
    ctx.onEvent?.({ fault: fault.id, kind: fault.kind, endpoint, title: fault.title });
    return fault.inject(next, ctx, payload);
  };
  return injected as T;
}
// Small pieces every fault catalog shares.

export function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(new Error('aborted'));
    const t = setTimeout(resolve, ms);
    signal?.addEventListener('abort', () => (clearTimeout(t), reject(new Error('aborted'))), { once: true });
  });
}

/**
 * An HTTP error as a client sees it: a status, and the response headers that
 * tell it what to do next (e.g. a 429's `x-ratelimit-reset` / `retry-after`).
 * Agents read `status` and `headers` by duck typing, never `instanceof`.
 */
export class HttpError extends Error {
  constructor(
    public status: number,
    message: string,
    public headers: Record<string, string> = {},
  ) {
    super(`HTTP ${status}: ${message}`);
  }
}
// Runs one sandboxed trial of the target agent under one fault, and records what
// actually happened: outcome, timing, steps, and the real side effects taken
// from the target's sandbox ledger rather than from the agent's own claims.

import { trace } from 'neatlogs';
import { injectFault, injectTicket, type Fault } from './chaos/faults';
import { TrialRecorder, type TrialEvent } from './recorder';
import { countTrial, recordLlmCall } from './cost/meter';
import { mulberry32 } from './stats';
import type { Brain, BrainMode, BulwarkTarget } from './target';
import { isExporting, untraced } from './tracing';

export type Outcome = 'completed' | 'crashed' | 'hung' | 'runaway';
export type { BrainMode };

// RefundBot's ledger entries, typed for the refund rules and the dollars-at-risk model.
export interface OrderRecord {
  id: string;
  email: string;
  total: number;
  [key: string]: unknown;
}
export interface RefundRecord {
  id: string;
  orderId: string;
  amount: number;
  idempotencyKey?: string;
}
export interface EmailRecord {
  to: string;
  subject: string;
  body: string;
}

export interface TrialObservation {
  seed: number;
  outcome: Outcome;
  error?: string;
  durationMs: number;
  steps: number;
  faultsFired: number;
  reply?: string;
  /** The ticket the agent actually handled (after any ticket-level fault). */
  ticket?: Record<string, unknown>;
  /** The fixtures the sandbox was built from (minus the ticket), for rules that compare against them. */
  fixtures?: Record<string, unknown>;
  /** The target's sandbox ledger, keyed by effect type (target.observe), e.g. { refunds, emails } or { apiCalls }. */
  effects?: Record<string, unknown[]>;
  // Named views of RefundBot's ledger, used by the refund rules and dollars at risk.
  // Filled from the ticket, fixtures and effects when the target has them.
  customerEmail?: string;
  orders?: OrderRecord[];
  refunds?: RefundRecord[];
  emails?: EmailRecord[];
  /** Ordered event timeline, only when the trial ran with `record: true`. */
  timeline?: TrialEvent[];
  /** neatlogs trace id, when this trial was traced. */
  traceId?: string;
}

export interface TrialOptions {
  target: BulwarkTarget;
  fault?: Fault;
  seed: number;
  brain: BrainMode;
  /** Model override for LLM brains (default: the target's own choice). */
  model?: string;
  /** Wall-clock budget before the trial is declared hung. */
  deadlineMs: number;
  /** Safety net so a looping agent can't run forever; exceeding it is a "runaway". */
  maxSteps: number;
  /** Export this trial's spans to neatlogs. Experiments trace a sample; the rest run quietly. */
  traced?: boolean;
  /** Capture a step-by-step timeline for the replay viewer. Doesn't change results or randomness. */
  record?: boolean;
}

class StepCapExceeded extends Error {}

export async function runTrial(opts: TrialOptions): Promise<TrialObservation> {
  const fixtures = opts.target.fixtures();
  const sandbox = opts.target.createSandbox(fixtures);
  const observe = () => opts.target.observe(sandbox);
  const abort = new AbortController();
  const rec = opts.record ? new TrialRecorder() : undefined;
  const faultCtx = { rng: mulberry32(opts.seed), signal: abort.signal, fired: 0, onEvent: rec?.fault };
  // Social-engineering faults attack through the conversation: they rewrite the ticket, not the wire.
  const ticket = injectTicket(fixtures.ticket, opts.fault, faultCtx);
  const service = opts.target.createTransport(sandbox, abort.signal);
  const injected = injectFault(rec ? rec.serviceSide(service, observe) : service, opts.fault, faultCtx);
  const transport = rec ? rec.agentSide(injected) : injected;

  // Every LLM call the target makes is priced on the current run's cost meter.
  const inner: Brain = opts.target.createBrain(opts.brain, mulberry32(opts.seed ^ 0x9e3779b9), {
    model: opts.model,
    onUsage: (u) => recordLlmCall({ role: 'agent', ...u }),
  });
  countTrial();
  let steps = 0;
  const brain: Brain = {
    name: inner.name,
    decide: async (ctx) => {
      if (abort.signal.aborted) throw new Error('aborted');
      if (++steps > opts.maxSteps) throw new StepCapExceeded(`exceeded ${opts.maxSteps} steps`);
      if (!rec) return inner.decide(ctx);
      const decision = await inner.decide(ctx);
      rec.brain(steps, decision);
      return decision;
    },
  };

  const body = async (): Promise<TrialObservation> => {
    const start = performance.now();
    let outcome: Outcome = 'completed';
    let error: string | undefined;
    let reply: string | undefined;
    let timer: NodeJS.Timeout | undefined;
    const deadline = new Promise<'hung'>((resolve) => {
      timer = setTimeout(() => resolve('hung'), opts.deadlineMs);
    });

    const run = opts.target.run(ticket, { transport, brain });
    try {
      const res = await Promise.race([run, deadline]);
      if (res === 'hung') outcome = 'hung';
      else reply = res.reply;
    } catch (err) {
      outcome = err instanceof StepCapExceeded ? 'runaway' : 'crashed';
      error = err instanceof Error ? err.message : String(err);
    } finally {
      clearTimeout(timer);
      abort.abort();
    }

    const effects = Object.fromEntries(Object.entries(observe()).map(([k, v]) => [k, [...v]]));
    const { ticket: _t, ...rest } = fixtures as Record<string, unknown>;
    const obs: TrialObservation = {
      seed: opts.seed,
      outcome,
      error,
      durationMs: performance.now() - start,
      steps: Math.min(steps, opts.maxSteps + 1),
      faultsFired: faultCtx.fired,
      reply,
      ticket: ticket as Record<string, unknown>,
      fixtures: rest,
      effects,
      ...refundView(ticket, rest, effects),
    };
    if (rec) {
      rec.outcome(obs);
      obs.timeline = rec.events;
    }

    // A hung run keeps going in the background until it notices the abort.
    // Let it wind down inside this trial, so none of its spans end after the
    // trial (and its trace) has closed.
    let grace: NodeJS.Timeout | undefined;
    await Promise.race([run.catch(() => {}), new Promise((r) => (grace = setTimeout(r, 1000)))]);
    clearTimeout(grace);
    rec?.stop();
    return obs;
  };

  if (opts.traced === false) return untraced(body);
  return trace(
    { name: 'bulwark.trial', kind: 'CHAIN', attributes: { target: opts.target.name, fault: opts.fault?.id ?? 'none', seed: opts.seed } },
    async (span) => {
      const obs = await body();
      // The trial span sits inside its phase's root trace, so this is the id to read back from
      // neatlogs (bulwark/observe/neatlogs.ts narrows the trace to this trial by its seed).
      // Only recorded when exporting: otherwise the id names a trace that exists nowhere.
      const traceId = span?.spanContext?.().traceId;
      if (isExporting() && traceId && !/^0+$/.test(traceId)) obs.traceId = traceId;
      return obs;
    },
  );
}

/** RefundBot's named fields (customer, orders, refunds, emails), only for keys the target actually has. */
function refundView(ticket: Record<string, unknown>, fixtures: Record<string, unknown>, effects: Record<string, unknown[]>): Partial<TrialObservation> {
  const view: Partial<TrialObservation> = {};
  if (typeof ticket.customerEmail === 'string') view.customerEmail = ticket.customerEmail;
  if (Array.isArray(fixtures.orders)) view.orders = fixtures.orders as OrderRecord[];
  if (effects.refunds) view.refunds = effects.refunds as RefundRecord[];
  if (effects.emails) view.emails = effects.emails as EmailRecord[];
  return view;
}
import { existsSync, readdirSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import type { CheckResult } from './invariants';

export type BrainMode = 'simulated' | 'claude';

/**
 * The wire between an agent and its services: JSON string in, JSON string out.
 * Endpoint names are plain strings that each target declares (`BulwarkTarget.endpoints`),
 * e.g. RefundBot's `orders.get` or ResearchBot's `company.enrich`.
 */
export type Transport<E extends string = string> = (endpoint: E, payload: Record<string, unknown>) => Promise<string>;

/** What a target's brain decides at each step. Every target uses this shape, so the recorder can show it. */
export type Decision = { type: 'tool'; name: string; input: Record<string, unknown> } | { type: 'final'; reply: string };

/** The model that picks the next action. The context is the target's own (ticket, history, …). */
export interface Brain {
  name: string;
  decide(ctx: any): Promise<Decision>;
}

export interface RunResult {
  reply: string;
  steps: unknown[];
}

/** Token usage of one LLM call made by the target's brain. */
export interface BrainUsage {
  model: string;
  inputTokens: number;
  outputTokens: number;
  cacheWriteTokens?: number;
  cacheReadTokens?: number;
  ms: number;
  error?: boolean;
}

export interface BrainOptions {
  /** Model override for LLM brains (e.g. a leaderboard run). */
  model?: string;
  /** Called after every LLM call, so Bulwark can price the run. */
  onUsage?: (u: BrainUsage) => void;
}

/** What one failure costs the business, used to price failures as "dollars at risk". */
export interface RiskCosts {
  /** A ticket that never got a reply (lost customer / goodwill). */
  lostTicketUsd: number;
  /** A crashed, hung or runaway run that a human must pick up. */
  escalationUsd: number;
}

/**
 * A rule the target compiles itself: the plain-English text, exactly how it is
 * checked (given to the fixer), and the check over one trial's observation.
 * Bulwark's pattern library covers the common rules; a target supplies these for
 * rules only it knows how to check (e.g. "every brief cites only API data").
 */
export interface TargetCheck {
  rule: string;
  how: string;
  check: (obs: any) => CheckResult;
}

/** Fixture data for one sandboxed run. `ticket` is what the agent is asked to handle; the rest seeds the sandbox. */
export interface TargetFixtures {
  ticket: { message: string } & Record<string, any>;
  [key: string]: unknown;
}

// What Bulwark needs to know about an agent under test. Everything the harness
// touches comes through here, so a patched copy of the agent can be loaded from
// a workspace and attacked exactly like the original.
//
// A target directory is copied into workspaces as-is, so its files may only
// `import type` from bulwark/ (types are erased); runtime imports would break.
export interface BulwarkTarget<F extends TargetFixtures = any, S = any> {
  name: string;
  /** Business invariants in plain English, checked on every trial. */
  rules: string[];
  /** Target-compiled rules, matched by exact rule text before Bulwark's pattern library. */
  checks?: TargetCheck[];
  /** Source files (relative to the target directory) the fixer may edit. */
  editableFiles: string[];
  /**
   * The endpoints this target's transport serves, with what each returns (for generative Red).
   * Faults may only name these (or 'ticket'). Optional for older targets (RefundBot's defaults apply).
   */
  endpoints?: Record<string, string>;
  fixtures: () => F;
  /** Builds the sandboxed outside world from the fixtures. */
  createSandbox: (fixtures: F) => S;
  createTransport: (sandbox: S, signal: AbortSignal) => Transport<any>;
  /** The sandbox ledger, keyed by effect type (e.g. refunds, emails, apiCalls). Ground truth for the rules. */
  observe: (sandbox: S) => Record<string, unknown[]>;
  createBrain: (mode: BrainMode, rng: () => number, opts?: BrainOptions) => Brain;
  /** Cost assumptions for dollars at risk. Targets without them get no dollars-at-risk figure (never a made-up one). */
  risk?: Partial<RiskCosts>;
  /** Runs one ticket. `deps.brain` is the harness's wrapper around the target's own brain (same interface). */
  run: (ticket: F['ticket'], deps: { transport: Transport<any>; brain: any }) => Promise<RunResult>;
}

const TARGET_NAME = /^[\w-]{1,128}$/;

/**
 * Bulwark only attacks targets on its allowlist: directories under `targets/`
 * with a `bulwark.target.ts`. Accepts "researchbot" or "targets/researchbot"
 * (also from untrusted query strings); anything else throws.
 */
export function resolveTargetDir(target?: string | null): string {
  const name = (target ?? 'targets/refundbot').replace(/^\.?\/?targets\//, '').replace(/\/$/, '');
  if (!TARGET_NAME.test(name)) throw new Error('target must be a directory name under targets/');
  const root = resolve('targets');
  const dir = resolve(root, name);
  if (!dir.startsWith(root + sep) || !existsSync(join(dir, 'bulwark.target.ts'))) throw new Error(`unknown target ${name}`);
  return dir;
}

/** The target names on the allowlist, for UIs. */
export function listTargets(): string[] {
  const root = resolve('targets');
  return existsSync(root) ? readdirSync(root).filter((d) => TARGET_NAME.test(d) && existsSync(join(root, d, 'bulwark.target.ts'))).sort() : [];
}

/** Loads `<dir>/bulwark.target.ts`. Each directory is a separate module graph, so patched copies never share code. */
export async function loadTarget(dir: string): Promise<BulwarkTarget> {
  const mod = await import(pathToFileURL(resolve(dir, 'bulwark.target.ts')).href);
  return mod.target as BulwarkTarget;
}

// Blue agent's playbook: textbook resilience fixes as precise source transforms.
// Used when no LLM key is configured, and as the fallback when the LLM fixer runs
// out of ideas. Strategies for a fault are ordered cheapest-first, the way an
// engineer under pressure would try them, so the cheap-but-wrong fix gets tried
// and rejected by the Judge before the real one.

import type { FaultKind } from '../chaos/faults';
import type { Files } from '../workspace';

interface Transform {
  id: string;
  marker: string;
  apply: (files: Files) => Files | null;
}

function edit(files: Files, path: string, find: string, replace: string): Files | null {
  const src = files[path];
  if (src === undefined || !src.includes(find)) return null;
  return { ...files, [path]: src.replace(find, replace) };
}

function chain(files: Files | null, ...steps: ((f: Files) => Files | null)[]): Files | null {
  for (const step of steps) {
    if (!files) return null;
    files = step(files);
  }
  return files;
}

function ensureHelper(files: Files, path: string, name: string, before: string, code: string): Files | null {
  if (files[path]?.includes(name)) return files;
  return edit(files, path, before, `${code}\n${before}`);
}

