// ResearchBot's tool runtime: what the model can call, and how each call reaches
// Crustdata. Written the way a team ships it on a deadline.

import { span } from 'neatlogs';
import type { EnrichResponse, PersonSearchResponse, Transport } from './crustdata';

export type ToolName = 'enrich_company' | 'search_people';

export const TOOL_SCHEMAS = [
  {
    name: 'enrich_company',
    description: 'Look up a company by its website domain (Crustdata company enrich). Returns name, domain, headcount, industry and total funding.',
    input_schema: {
      type: 'object' as const,
      properties: { domain: { type: 'string', description: 'bare website domain, e.g. retool.com' } },
      required: ['domain'],
    },
  },
  {
    name: 'search_people',
    description: "Find a company's key decision-makers (CXOs and VPs) by its website domain (Crustdata person search). Returns name and title for each.",
    input_schema: {
      type: 'object' as const,
      properties: { domain: { type: 'string' }, limit: { type: 'number', description: 'people per page, default 3' } },
      required: ['domain'],
    },
  },
];

export interface CompanyFacts {
  name: string;
  domain: string;
  headcount: number | null;
  industry: string | null;
  fundingUsd: number | null;
}

export interface PersonFacts {
  id: number;
  name: string;
  title: string;
}

/** Company enrich sections the brief needs (2 credits per record whatever the sections, per Crustdata pricing). */
export const COMPANY_FIELDS = ['basic_info', 'headcount', 'funding', 'taxonomy'];
export const LEADER_SENIORITY = ['CXO', 'Vice President'];

export function enrichRequest(domain: string): Record<string, unknown> {
  return { domains: [domain], fields: COMPANY_FIELDS };
}

/** Current CXOs and VPs at the company, by website domain. Only name and title come back (base price + one experience filter). */
export function peopleQuery(domain: string, limit: number): Record<string, unknown> {
  return {
    filters: {
      op: 'and',
      conditions: [
        { field: 'experience.employment_details.current.company_website_domain', type: '=', value: domain },
        { field: 'experience.employment_details.current.seniority_level', type: 'in', value: LEADER_SENIORITY },
      ],
    },
    fields: ['basic_profile.name', 'basic_profile.current_title'],
    sorts: [{ field: 'crustdata_person_id', order: 'asc' }],
    limit,
  };
}

export type Tools = Record<ToolName, (input: Record<string, unknown>) => Promise<unknown>>;

export function createTools(transport: Transport): Tools {
  return {
    enrich_company: span({ kind: 'TOOL', name: 'enrich_company', toolName: 'enrich_company' }, async (input) => {
      const raw = await transport('company.enrich', enrichRequest(String(input.domain)));
      const company = (JSON.parse(raw) as EnrichResponse)[0].matches[0].company_data;
      return {
        name: company.basic_info!.name,
        domain: company.basic_info!.primary_domain,
        headcount: company.headcount!.total,
        industry: company.taxonomy!.professional_network_industry,
        fundingUsd: company.funding!.total_investment_usd,
      };
    }),

    search_people: span({ kind: 'TOOL', name: 'search_people', toolName: 'search_people' }, async (input) => {
      const people: PersonFacts[] = [];
      let cursor: string | null = null;
      // Collect every page of leaders.
      do {
        const raw = await transport('person.search', { ...peopleQuery(String(input.domain), Number(input.limit ?? 3)), ...(cursor ? { cursor } : {}) });
        const page = JSON.parse(raw) as PersonSearchResponse;
        for (const p of page.profiles) people.push({ id: p.crustdata_person_id, name: p.basic_profile.name, title: p.basic_profile.current_title ?? '' });
        cursor = page.next_cursor;
      } while (cursor);
      return people;
    }),
  };
}
// ResearchBot: a small research agent. Given "Brief me on <company domain> and
// its key decision-makers", it calls Crustdata and answers with a JSON company
// brief. Bulwark's second demo target.

import { trace } from 'neatlogs';
import type { Transport } from './crustdata';
import { createTools, type ToolName } from './tools';

export interface Ticket {
  id: string;
  requester: string;
  message: string;
}

/** The answer: a brief, or an explicit "not found". */
export type Brief =
  | {
      status: 'ok';
      name: string;
      domain: string;
      headcount: number | null;
      industry: string | null;
      fundingUsd: number | null;
      people: { name: string; title: string }[];
    }
  | { status: 'not found'; domain: string | null; reason?: string };

export interface Step {
  tool: ToolName;
  input: Record<string, unknown>;
  output: unknown;
}

export interface BrainContext {
  ticket: Ticket;
  history: Step[];
}

export type Decision = { type: 'tool'; name: ToolName; input: Record<string, unknown> } | { type: 'final'; reply: string };

// The model that picks the next action. Swappable so trials can run against a
// real LLM or a cheap deterministic simulation of one.
export interface Brain {
  name: string;
  decide(ctx: BrainContext): Promise<Decision>;
}

export interface RunResult {
  reply: string;
  steps: Step[];
}

export const SYSTEM_PROMPT =
  'You are ResearchBot, a B2B research assistant. For the company in the request, call enrich_company with its ' +
  'website domain, then search_people for its key decision-makers. Then reply with ONLY a JSON object, no prose: ' +
  '{"status":"ok","name":string,"domain":string,"headcount":number|null,"industry":string|null,"fundingUsd":number|null,' +
  '"people":[{"name":string,"title":string}] (2-3 people)}. If the company cannot be found, reply ' +
  '{"status":"not found","domain":string}.';

export async function runResearchBot(ticket: Ticket, deps: { transport: Transport; brain: Brain }): Promise<RunResult> {
  return trace({ name: 'researchbot.run', kind: 'AGENT', attributes: { ticketId: ticket.id, brain: deps.brain.name } }, async () => {
    const tools = createTools(deps.transport);
    const history: Step[] = [];
    while (true) {
      const decision = await deps.brain.decide({ ticket, history });
      if (decision.type === 'final') return { reply: decision.reply, steps: history };
      const output = await tools[decision.name](decision.input);
      history.push({ tool: decision.name, input: decision.input, output });
    }
  });
}
// Crustdata (docs.crustdata.com, API version 2025-11-01) as ResearchBot sees it:
// the response shapes of the two endpoints it calls, a live client (used only to
// record), and CrustdataCassette: the sandbox every trial runs against. It
// replays recorded responses, so hundreds of chaos trials cost zero credits and
// replay deterministically, and its ledger (every call, with the credits the real
// API charged for it) is the ground truth Bulwark checks the rules against.

import { readdirSync, readFileSync } from 'node:fs';

export const API_BASE = 'https://api.crustdata.com';
export const API_VERSION = '2025-11-01';

// The wire boundary: JSON string in, JSON string out, which is where real network
// faults happen and where Bulwark's chaos layer intercepts.
export type Endpoint = 'company.enrich' | 'person.search';
export type Transport = (endpoint: Endpoint, payload: Record<string, unknown>) => Promise<string>;

export const ENDPOINT_PATHS: Record<Endpoint, string> = {
  'company.enrich': '/company/enrich',
  'person.search': '/person/search',
};

// --- Response shapes (the subset ResearchBot reads) ---

export interface CompanyData {
  crustdata_company_id?: number;
  basic_info?: { name?: string; primary_domain?: string; website?: string; year_founded?: number; employee_count_range?: string };
  headcount?: { total?: number };
  funding?: { total_investment_usd?: number; last_round_type?: string; last_fundraise_date?: string };
  taxonomy?: { professional_network_industry?: string };
}

/** POST /company/enrich: one entry per identifier; `matches` is empty when nothing matched. */
export type EnrichResponse = { matched_on: string; match_type: string; matches: { confidence_score: number; company_data: CompanyData }[] }[];

export interface PersonProfile {
  crustdata_person_id: number;
  basic_profile: { name: string; current_title?: string; headline?: string };
}

/** POST /person/search: one page of profiles; `next_cursor` is null on the last page. */
export interface PersonSearchResponse {
  profiles: PersonProfile[];
  next_cursor: string | null;
  total_count: number;
}

export class HttpError extends Error {
  constructor(
    public status: number,
    message: string,
    public headers: Record<string, string> = {},
  ) {
    super(`HTTP ${status}: ${message}`);
  }
}

// --- Cassettes ---

/** One recorded request/response, exactly as the real API answered it. */
export interface Interaction {
  endpoint: Endpoint;
  path: string;
  request: Record<string, unknown>;
  status: number;
  /** The real `X-Credits-Used` header (estimated from the price list in synthetic cassettes). */
  creditsUsed: number;
  response: unknown;
  /** Round-trip time when it was recorded. */
  ms?: number;
}

export interface Cassette {
  /** true for hand-written cassettes; recorded cassettes are false. Never mix the two up. */
  synthetic: boolean;
  domain: string;
  apiVersion: string;
  recordedAt: string;
  note?: string;
  interactions: Interaction[];
}

/** One call the sandbox served: the ledger entry the rules read. */
export interface ApiCall {
  endpoint: Endpoint;
  request: Record<string, unknown>;
  status: number;
  creditsUsed: number;
  response: unknown;
  /** `hit`: served from a recording. `miss`: nothing recorded, answered the way the API answers no match. */
  cassette: 'hit' | 'miss';
}

const CASSETTE_DIR = new URL('./cassettes/', import.meta.url);

/** Canonical key for a request: endpoint + JSON with sorted keys, so field order never matters. */
export function requestKey(endpoint: string, request: unknown): string {
  const canon = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(canon)
      : v && typeof v === 'object'
        ? Object.fromEntries(Object.keys(v).filter((k) => (v as Record<string, unknown>)[k] !== undefined).sort().map((k) => [k, canon((v as Record<string, unknown>)[k])]))
        : v;
  return `${endpoint} ${JSON.stringify(canon(request))}`;
}

export function loadCassettes(dir: URL = CASSETTE_DIR): Cassette[] {
  return readdirSync(dir)
    .filter((f) => f.endsWith('.json') && f !== 'manifest.json')
    .sort()
    .map((f) => JSON.parse(readFileSync(new URL(f, dir), 'utf8')) as Cassette);
}

